/* Cloud-native infrastructure guide — configurator and upgrade walkthrough.
 *
 * Vanilla ES5. No build step, no dependencies, no network calls. The data
 * comes from site/data.json, generated by scripts/build_site.py from
 * catalog/*.json and compatibility/version-matrix.md.
 *
 * Keep this file ES5: tests/test_site_render.py runs it in dukpy (Duktape).
 * No let/const, no arrow functions, no template literals.
 */
(function () {
  "use strict";

  var DATA = null;
  var state = {
    method: null,
    cluster: null,
    choices: {},
    values: {},
    page: 0,
    view: "wizard",
    upgrade: { flow: null, target: "" }
  };

  /* ------------------------------------------------------------------ */
  /* tiny helpers                                                       */
  /* ------------------------------------------------------------------ */

  function el(tag, attrs, children) {
    var node = document.createElement(tag);
    if (attrs) {
      Object.keys(attrs).forEach(function (k) {
        if (k === "class") node.className = attrs[k];
        else if (k === "text") node.textContent = attrs[k];
        else if (k === "html") node.innerHTML = attrs[k];
        else if (k.slice(0, 2) === "on") node.addEventListener(k.slice(2), attrs[k]);
        else if (attrs[k] !== null && attrs[k] !== undefined) node.setAttribute(k, attrs[k]);
      });
    }
    (children || []).forEach(function (c) {
      if (c === null || c === undefined) return;
      node.appendChild(typeof c === "string" ? document.createTextNode(c) : c);
    });
    return node;
  }

  function $(id) { return document.getElementById(id); }

  function clear(node) { while (node.firstChild) node.removeChild(node.firstChild); }

  function toast(msg) {
    var t = $("toast");
    if (!t) return;
    t.textContent = msg;
    t.className = "toast show";
    setTimeout(function () { t.className = "toast"; }, 2200);
  }

  function download(filename, text) {
    var blob = new Blob([text], { type: "text/plain;charset=utf-8" });
    var url = URL.createObjectURL(blob);
    var a = document.createElement("a");
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(function () { URL.revokeObjectURL(url); }, 500);
  }

  function copyText(text) {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text);
      return;
    }
    var ta = el("textarea", { text: text });
    document.body.appendChild(ta);
    ta.select();
    try { document.execCommand("copy"); } catch (e) { /* clipboard blocked */ }
    document.body.removeChild(ta);
  }

  function num(id) {
    var n = parseInt(state.values[id], 10);
    return isNaN(n) ? 0 : n;
  }

  function lines(text) {
    return String(text || "").split("\n").map(function (s) { return s.trim(); })
      .filter(function (s) { return s.length > 0; });
  }

  function ipAdd(ip, offset) {
    var p = String(ip || "").split(".");
    if (p.length !== 4) return "";
    var v = (parseInt(p[0], 10) * 16777216) + (parseInt(p[1], 10) * 65536) +
            (parseInt(p[2], 10) * 256) + parseInt(p[3], 10);
    if (isNaN(v)) return "";
    v += offset;
    return [Math.floor(v / 16777216) % 256, Math.floor(v / 65536) % 256,
            Math.floor(v / 256) % 256, v % 256].join(".");
  }

  /* role -> [{name, ip}] */
  function roleNodes(role, count, startIp, offset) {
    var out = [];
    for (var i = 0; i < count; i++) {
      out.push({
        name: state.values.nodePrefix + "-" + role + "-" + (i + 1),
        ip: ipAdd(startIp, offset + i)
      });
    }
    return out;
  }

  function cmp(componentId) {
    return DATA.components.filter(function (c) { return c.id === componentId; })[0] || null;
  }

  function optionOf(componentId) {
    var c = cmp(componentId);
    if (!c) return null;
    var chosen = state.choices[componentId];
    return c.options.filter(function (o) { return o.id === chosen; })[0] || null;
  }

  function optionTitle(componentId) {
    var o = optionOf(componentId);
    return o ? o.title : "—";
  }

  function gpuEnabled() {
    return state.choices.gpu === "mig" || state.choices.gpu === "timeslicing";
  }

  function storageMode() {
    var v = String(state.choices.storage || "");
    return v.indexOf("cephadm") === 0 ? v : "rook";
  }

  /* ------------------------------------------------------------------ */
  /* node topology and derived blocks                                   */
  /* ------------------------------------------------------------------ */

  function topology() {
    var start = state.values.appNodeIpStart;
    var cp = roleNodes("cp", num("appCpCount"), start, 0);
    var w = roleNodes("w", num("appWorkerCount"), start, cp.length);
    var g = gpuEnabled() ? roleNodes("gpu", num("gpuCount"), start, cp.length + w.length) : [];

    var mgmt = [];
    for (var i = 0; i < num("mgmtWorkerCount"); i++) {
      mgmt.push({
        name: state.values.nodePrefix + "-mgmt-" + (i + 1),
        ip: ipAdd(state.values.mgmtIpStart, i)
      });
    }

    var cephRoles = { mon: [], mgr: [], osd: [], mds: [], rgw: [] };
    if (storageMode().indexOf("cephadm") === 0) {
      var cp2 = state.values.cephHostPrefix || "ceph";
      var spec = [
        ["mon", "cephMonCount", "cephMonIpStart"],
        ["mgr", "cephMgrCount", "cephMgrIpStart"],
        ["osd", "cephOsdCount", "cephOsdIpStart"],
        ["mds", "cephMdsCount", "cephMdsIpStart"],
        ["rgw", "cephRgwCount", "cephRgwIpStart"]
      ];
      spec.forEach(function (role) {
        for (var n = 0; n < num(role[1]); n++) {
          cephRoles[role[0]].push({
            name: cp2 + "-" + role[0] + "-" + (n + 1),
            ip: ipAdd(state.values[role[2]], n)
          });
        }
      });
    }
    var ceph = cephRoles.mon.concat(cephRoles.mgr, cephRoles.osd, cephRoles.mds, cephRoles.rgw);

    var edge = [];
    for (var k = 0; k < num("edgeCount"); k++) {
      edge.push({ name: "lb-" + (k + 1), ip: ipAdd(state.values.edgeIpStart, k) });
    }

    return { cp: cp, w: w, gpu: g, mgmt: mgmt, ceph: ceph, cephRoles: cephRoles, edge: edge };
  }

  function names(list) {
    return list.map(function (n) { return n.name; }).join(" ");
  }

  function tsvRows(list, role) {
    return list.map(function (n) { return role + "\t" + n.name + "\t" + n.ip; }).join("\n");
  }

  function cephAddCmds(list, role) {
    return list.map(function (n) {
      return "ceph orch host add " + n.name + " " + n.ip + " --labels " + role;
    }).join("\n");
  }

  function placement(list) {
    return list.map(function (n) { return "    - " + n.name; }).join("\n");
  }

  function ips(list) {
    return list.map(function (n) { return n.ip; }).join(" ");
  }

  function hostLines(list) {
    return list.map(function (n) {
      return n.name + " ansible_host=" + n.ip + " ip=" + n.ip;
    }).join("\n");
  }

  function derived() {
    var t = topology();

    var gpuGroup = "";
    if (t.gpu.length) {
      gpuGroup = "\n[k8s-node:children]\ngpu-node\n\n[gpu-node]\n" + hostLines(t.gpu);
    }

    var extraMirrors = lines(state.values.extraRegistries).map(function (line) {
      return "  - prefix: \"" + line + "\"\n" +
             "    mirrors:\n" +
             "      - host: \"https://" + line + "\"\n" +
             "        capabilities: [\"pull\", \"resolve\"]";
    }).join("\n");

    var idp = state.choices.idpIntegration || [];
    var targets = [];
    var idpComp = cmp("idpIntegration");
    if (idpComp && Object.prototype.toString.call(idp) === "[object Array]") {
      idpComp.options.forEach(function (o) {
        if (idp.indexOf(o.id) !== -1 && o.id !== "none") {
          targets.push("- **" + o.title + "** → `" + o.doc + "`");
        }
      });
    }

    var engine = storageMode() === "cephadm-docker" ? "docker" : "podman";

    return {
      appCpHosts: hostLines(t.cp),
      appWorkerHosts: hostLines(t.w),
      appCpCount: String(t.cp.length),
      appWorkerCount: String(t.w.length),
      gpuHosts: hostLines(t.gpu),
      gpuHostList: t.gpu.map(function (n) { return n.ip; }).join(", "),
      gpuGroup: gpuGroup,
      gpuReplicas: String(t.gpu.length > 1 ? 2 : 1),
      firstGpuNode: t.gpu.length ? t.gpu[0].name : "",
      mgmtHosts: hostLines(t.mgmt),
      mgmtCount: String(t.mgmt.length),
      cephHosts: hostLines(t.ceph),
      cephAllNames: names(t.ceph),
      cephMonHosts: hostLines(t.cephRoles.mon),
      cephMonNames: names(t.cephRoles.mon),
      cephMonIps: ips(t.cephRoles.mon),
      cephMonPlacement: placement(t.cephRoles.mon),
      cephMgrPlacement: placement(t.cephRoles.mgr),
      cephOsdPlacement: placement(t.cephRoles.osd),
      cephMdsPlacement: placement(t.cephRoles.mds),
      cephRgwPlacement: placement(t.cephRoles.rgw),
      cephMgrNames: names(t.cephRoles.mgr),
      cephMgrIps: ips(t.cephRoles.mgr),
      cephOsdHosts: hostLines(t.cephRoles.osd),
      cephOsdNames: names(t.cephRoles.osd),
      cephOsdIps: ips(t.cephRoles.osd),
      cephMdsNames: names(t.cephRoles.mds),
      cephMdsIps: ips(t.cephRoles.mds),
      cephRgwNames: names(t.cephRoles.rgw),
      cephRgwIps: ips(t.cephRoles.rgw),
      cephHostAddCmds: cephAddCmds(t.cephRoles.mon, "mon") + "\n" +
        cephAddCmds(t.cephRoles.mgr, "mgr") + "\n" +
        cephAddCmds(t.cephRoles.osd, "osd") + "\n" +
        cephAddCmds(t.cephRoles.mds, "mds") + "\n" +
        cephAddCmds(t.cephRoles.rgw, "rgw"),
      nodeRows: [
        tsvRows(t.cp, "control-plane"), tsvRows(t.w, "worker"), tsvRows(t.gpu, "gpu"),
        tsvRows(t.mgmt, "management"), tsvRows(t.cephRoles.mon, "ceph-mon"),
        tsvRows(t.cephRoles.mgr, "ceph-mgr"), tsvRows(t.cephRoles.osd, "ceph-osd"),
        tsvRows(t.cephRoles.mds, "ceph-mds"), tsvRows(t.cephRoles.rgw, "ceph-rgw"),
        tsvRows(t.edge, "edge")
      ].filter(function (x) { return x; }).join("\n"),
      cephHostList: t.ceph.map(function (n) { return n.name + "=" + n.ip; }).join(", "),
      cephOtherIps: t.ceph.slice(1).map(function (n) { return n.ip; }).join(" "),
      cephMonIp: t.ceph.length ? t.ceph[0].ip : "",
      cephEngine: engine,
      cephEngineFlag: engine === "docker" ? "--docker" : "",
      edgeHosts: hostLines(t.edge),
      edgeHostList: t.edge.map(function (n) { return n.name + "=" + n.ip; }).join(", "),
      edgeL1: t.edge.length ? t.edge[0].ip : "",
      edgePeerList: t.edge.slice(1).map(function (n) { return "        " + n.ip; }).join("\n"),
      extraRegistryMirrors: extraMirrors,
      idpTargets: targets.length ? targets.join("\n") : "- none selected",
      registryAuth: state.values.registryAuth || "",
      vrrpAuthPass: state.values.vrrpAuthPass || "",
      revision: String(DATA.versions.istio || "").replace(/\./g, "-"),
      istioProfile: state.choices.serviceMesh === "istio-ambient" ? "ambient" : "default",
      totalNodes: String(t.cp.length + t.w.length + t.gpu.length + t.mgmt.length + t.ceph.length + t.edge.length)
    };
  }

  /* ------------------------------------------------------------------ */
  /* template rendering                                                 */
  /* ------------------------------------------------------------------ */

  function renderTemplate(tpl) {
    var d = derived();
    var ctx = {
      value: function (id) { return state.values[id] === undefined ? "" : state.values[id]; },
      choice: function (id) {
        var v = state.choices[id];
        if (v !== undefined && v !== null) {
          return Object.prototype.toString.call(v) === "[object Array]" ? v.join(",") : String(v);
        }
        var cm = DATA.clusterMethods.filter(function (m) { return m.id === id; })[0];
        return cm && state.cluster === id ? id : "";
      },
      version: function (key) { return DATA.versions[key] || "UNVERIFIED"; }
    };

    return tpl.replace(/\{\{\s*([a-zA-Z]+)\.([a-zA-Z0-9_-]+)\s*\}\}/g, function (m, ns, key) {
      if (ctx[ns] && typeof ctx[ns] === "function") return ctx[ns](key);
      return "";
    }).replace(/\{\{\s*([a-zA-Z0-9_-]+)\s*\}\}/g, function (m, key) {
      return d[key] === undefined ? "" : String(d[key]);
    });
  }

  function asArray(v) {
    return Object.prototype.toString.call(v) === "[object Array]";
  }

  function exportApplies(exp) {
    if (exp.when) {
      var chosen = state.choices[exp.when.component];
      var want = exp.when.values || [];
      if (asArray(chosen)) {
        for (var i = 0; i < chosen.length; i++) if (want.indexOf(chosen[i]) !== -1) return true;
        return false;
      }
      return want.indexOf(chosen) !== -1;
    }
    if (!exp.component) return true;
    if (exp.component === "clusterMethods") return state.cluster === "kubespray";
    var c = state.choices[exp.component];
    if (asArray(c)) return c.length > 0 && c.indexOf("none") === -1;
    return !!c && c !== "none";
  }

  /* ------------------------------------------------------------------ */
  /* step gating                                                        */
  /* ------------------------------------------------------------------ */

  function stepApplies(step) {
    if (!step.when) return true;

    if (step.when.component_any) {
      var any = step.when.component_any;
      var hitAny = false;
      Object.keys(any).forEach(function (k) {
        var got = state.choices[k];
        var allowed = asArray(any[k]) ? any[k] : [any[k]];
        if (asArray(got)) {
          for (var n = 0; n < got.length; n++) if (allowed.indexOf(got[n]) !== -1) hitAny = true;
        } else if (allowed.indexOf(got) !== -1) {
          hitAny = true;
        }
      });
      if (!hitAny) return false;
    }

    var want = step.when.component || {};
    var keys = Object.keys(want);
    for (var i = 0; i < keys.length; i++) {
      var k = keys[i];
      var w = want[k];
      var got = state.choices[k];
      var list = asArray(w) ? w : [w];
      if (asArray(got)) {
        var hit = false;
        for (var j = 0; j < got.length; j++) if (list.indexOf(got[j]) !== -1) hit = true;
        if (!hit) return false;
      } else if (list.indexOf(got) === -1) {
        return false;
      }
    }
    return true;
  }

  /* ------------------------------------------------------------------ */
  /* wizard                                                             */
  /* ------------------------------------------------------------------ */

  function renderCrumbs() {
    var box = $("crumbs");
    if (!box) return;
    clear(box);
    DATA.pages.forEach(function (p, i) {
      box.appendChild(el("li", {
        class: i === state.page ? "on" : "",
        onclick: function () { gotoPage(i); }
      }, [
        el("span", { class: "num", text: String(i + 1) }),
        el("span", { text: p.title })
      ]));
    });
  }

  function fieldNode(v) {
    var input;
    if (v.type === "bool") {
      input = el("input", {
        type: "checkbox",
        checked: state.values[v.id] === "true" ? "checked" : null,
        onchange: function () { state.values[v.id] = input.checked ? "true" : "false"; }
      });
      return el("div", { class: "field bool" }, [
        el("label", { class: "check" }, [input, el("span", { text: v.label })]),
        v.hint ? el("div", { class: "hint", text: v.hint }) : null
      ]);
    }
    if (v.type === "select") {
      input = el("select", {
        onchange: function () { state.values[v.id] = input.value; }
      });
      (v.options || []).forEach(function (o) {
        input.appendChild(el("option", {
          value: o, text: o,
          selected: o === state.values[v.id] ? "selected" : null
        }));
      });
      if ((v.options || []).indexOf(state.values[v.id]) === -1 && v.options && v.options.length) {
        state.values[v.id] = v.options[0];
        input.value = v.options[0];
      }
    } else if (v.type === "lines") {
      input = el("textarea", {
        rows: "3",
        oninput: function () { state.values[v.id] = input.value; }
      });
      input.value = state.values[v.id] === undefined ? "" : state.values[v.id];
    } else {
      input = el("input", {
        type: v.secret ? "password" : (v.type === "number" ? "number" : "text"),
        value: state.values[v.id] === undefined ? "" : state.values[v.id],
        min: v.min !== undefined ? String(v.min) : null,
        max: v.max !== undefined ? String(v.max) : null,
        placeholder: v.required ? "required" : "optional",
        oninput: function () { state.values[v.id] = input.value; }
      });
    }
    return el("div", { class: "field" + (v.secret ? " secret" : "") }, [
      el("label", { text: v.label }),
      input,
      v.hint ? el("div", { class: "hint", text: v.hint }) : null
    ]);
  }

  function componentNode(c) {
    var card = el("div", { class: "comp" }, [
      el("h4", {}, [
        el("span", { text: c.title }),
        el("span", {
          class: "req",
          text: c.multi ? "multi select" : (c.required ? "required" : "optional")
        })
      ])
    ]);
    if (c.note) card.appendChild(el("p", { class: "hint", text: c.note }));

    var opts = el("div", { class: "options" });
    var chosen = state.choices[c.id];

    c.options.forEach(function (o) {
      var on = c.multi
        ? (asArray(chosen) ? chosen.indexOf(o.id) !== -1 : false)
        : chosen === o.id;

      opts.appendChild(el("label", { class: "opt" + (on ? " on" : "") }, [
        el("input", {
          type: c.multi ? "checkbox" : "radio",
          name: "c-" + c.id,
          value: o.id,
          checked: on ? "checked" : null,
          onchange: function () { choose(c, o.id); }
        }),
        el("div", { class: "opt-body" }, [
          el("div", { class: "opt-title", text: o.title }),
          o.versionKey && DATA.versions[o.versionKey]
            ? el("div", { class: "opt-note", text: DATA.versions[o.versionKey] }) : null,
          o.note ? el("div", { class: "opt-note", text: o.note }) : null,
          o.warning ? el("div", { class: "opt-warn", text: "Warning: " + o.warning }) : null
        ])
      ]));
    });

    card.appendChild(opts);
    return card;
  }

  function choose(component, optionId) {
    if (!component.multi) {
      state.choices[component.id] = optionId;
      renderPage();
      return;
    }
    var cur = state.choices[component.id];
    if (!asArray(cur)) cur = [];
    if (optionId === "none") {
      state.choices[component.id] = ["none"];
    } else {
      cur = cur.filter(function (x) { return x !== "none"; });
      var at = cur.indexOf(optionId);
      if (at === -1) cur.push(optionId); else cur.splice(at, 1);
      state.choices[component.id] = cur.length ? cur : ["none"];
    }
    renderPage();
  }

  function nodeListCard(title, list) {
    return el("div", { class: "card plain" }, [
      el("h3", { text: title }),
      el("pre", {
        class: "mini",
        text: list.map(function (n) { return n.name + "  " + n.ip; }).join("\n") || "—"
      })
    ]);
  }

  function renderPage() {
    var page = DATA.pages[state.page];
    var box = $("page");
    if (!page || !box) return;
    clear(box);

    box.appendChild(el("h2", { text: page.title }));
    box.appendChild(el("p", { class: "hint", text: page.subtitle }));

    if (page.id === "p1") {
      var mbox = el("div", { class: "options" });
      DATA.methods.forEach(function (m) {
        var on = state.method === m.id;
        mbox.appendChild(el("label", { class: "opt" + (on ? " on" : "") }, [
          el("input", {
            type: "radio", name: "method", value: m.id, checked: on ? "checked" : null,
            onchange: function () { state.method = m.id; renderPage(); }
          }),
          el("div", { class: "opt-body" }, [
            el("div", { class: "opt-title", text: m.title }),
            el("div", { class: "opt-note", text: m.summary })
          ])
        ]));
      });
      box.appendChild(el("div", { class: "card" }, [
        el("h3", { text: "Deployment method" }), mbox
      ]));

      var method = DATA.methods.filter(function (m) { return m.id === state.method; })[0];
      if (method) {
        box.appendChild(el("div", { class: "card plain" }, [
          el("h3", { text: "Requirements" }),
          el("p", { class: "hint", text: "Best for: " + method.bestFor }),
          el("ul", {}, method.requirements.map(function (r) { return el("li", { text: r }); }))
        ]));
      }

      var cbox = el("div", { class: "options" });
      DATA.clusterMethods.forEach(function (m) {
        var on = state.cluster === m.id;
        cbox.appendChild(el("label", { class: "opt" + (on ? " on" : "") }, [
          el("input", {
            type: "radio", name: "cluster", value: m.id, checked: on ? "checked" : null,
            onchange: function () { state.cluster = m.id; renderPage(); }
          }),
          el("div", { class: "opt-body" }, [
            el("div", { class: "opt-title", text: m.title }),
            el("div", { class: "opt-note", text: m.summary })
          ])
        ]));
      });
      box.appendChild(el("div", { class: "card" }, [
        el("h3", { text: "Cluster method" }), cbox
      ]));

      var cm = DATA.clusterMethods.filter(function (m) { return m.id === state.cluster; })[0];
      if (cm) {
        var rel = el("ul", {});
        Object.keys(cm.versions || {}).forEach(function (k) {
          var r = cm.versions[k];
          rel.appendChild(el("li", {
            text: k + ": Kubernetes " + r.kubernetes + ", etcd " + r.etcd +
              ", containerd " + r.containerd + ", Cilium " + r.cilium +
              ", Ansible " + r.ansible + " / Python " + r.python
          }));
        });
        box.appendChild(el("div", { class: "card plain" }, [
          el("h3", { text: "Supported releases" }), rel
        ]));
      }
    }

    if (page.fields && page.fields.length) {
      var grid = el("div", { class: "values" });
      page.fields.forEach(function (id) {
        var v = DATA.values.filter(function (x) { return x.id === id; })[0];
        if (v) grid.appendChild(fieldNode(v));
      });
      box.appendChild(el("div", { class: "card" }, [el("h3", { text: "Values" }), grid]));
    }

    if (page.components && page.components.length) {
      var comps = el("div", { class: "components" });
      page.components.forEach(function (id) {
        var c = cmp(id);
        if (c) comps.appendChild(componentNode(c));
      });
      box.appendChild(el("div", { class: "card plain" }, [
        el("h3", { text: "Components" }), comps
      ]));
    }

    var t = topology();
    if (page.id === "p2") {
      box.appendChild(nodeListCard("Nodes generated", t.cp.concat(t.w, t.gpu)));
    }
    if (page.id === "p3") {
      box.appendChild(nodeListCard("Management nodes generated", t.mgmt));
    }
    if (page.id === "p5" && storageMode().indexOf("cephadm") === 0) {
      var roles = t.cephRoles;
      [["MON", roles.mon], ["MGR", roles.mgr], ["OSD", roles.osd],
       ["MDS", roles.mds], ["RGW", roles.rgw]].forEach(function (r) {
        box.appendChild(nodeListCard("Ceph " + r[0] + " hosts generated", r[1]));
      });
    }
    if (page.id === "p6") {
      box.appendChild(nodeListCard("Edge nodes generated", t.edge));
    }

    if ($("prev")) $("prev").disabled = state.page === 0;
    if ($("page-count")) {
      $("page-count").textContent = (state.page + 1) + " / " + DATA.pages.length;
    }
    if ($("next")) {
      $("next").textContent = state.page === DATA.pages.length - 1 ? "Review" : "Next";
    }
  }

  function gotoPage(i) {
    state.page = Math.max(0, Math.min(DATA.pages.length - 1, i));
    show("wizard");
    renderCrumbs();
    renderPage();
    if (window.scrollTo) window.scrollTo(0, 0);
  }

  /* ------------------------------------------------------------------ */
  /* review                                                             */
  /* ------------------------------------------------------------------ */

  function sizingRows() {
    var t = topology();
    var rows = [];
    function add(label, list, cpuId, memId, diskId, dataId) {
      if (!list.length) return;
      var cpu = num(cpuId), mem = num(memId), disk = num(diskId);
      var data = 0;
      if (dataId) {
        (Object.prototype.toString.call(dataId) === "[object Array]" ? dataId : [dataId]).forEach(function (id) {
          data += num(id);
        });
      }
      rows.push([label, String(list.length), String(cpu), String(mem), String(disk + data)]);
    }
    add("Application control plane", t.cp, "appCpCpu", "appCpMemGb", "appCpDiskGb", null);
    add("Application workers", t.w, "appWorkerCpu", "appWorkerMemGb", "appWorkerDiskGb", "appWorkerDataDiskGb");
    if (t.gpu.length) add("GPU workers", t.gpu, "gpuCpu", "gpuMemGb", "gpuDiskGb", null);
    add("Management cluster", t.mgmt, "mgmtCpu", "mgmtMemGb", "mgmtDiskGb", null);
    if (t.ceph.length) {
      var r = t.cephRoles;
      add("Ceph MON hosts", r.mon, "cephCpu", "cephMemGb", "cephSystemDiskGb", null);
      add("Ceph MGR hosts", r.mgr, "cephCpu", "cephMemGb", "cephSystemDiskGb", null);
      add("Ceph OSD hosts", r.osd, "cephCpu", "cephMemGb", "cephSystemDiskGb", ["cephOsdDataDiskGb", "cephOsdDbDiskGb"]);
      add("Ceph MDS hosts", r.mds, "cephCpu", "cephMemGb", "cephSystemDiskGb", null);
      add("Ceph RGW hosts", r.rgw, "cephCpu", "cephMemGb", "cephSystemDiskGb", null);
    }
    add("Edge nodes", t.edge, "edgeCpu", "edgeMemGb", "edgeDiskGb", null);
    return rows;
  }

  function renderReview() {
    var method = DATA.methods.filter(function (m) { return m.id === state.method; })[0];
    var cm = DATA.clusterMethods.filter(function (m) { return m.id === state.cluster; })[0];

    if ($("plan-summary")) {
      $("plan-summary").textContent =
        (method ? method.title : "—") + " · " + (cm ? cm.title : "—") + " · " +
        DATA.components.length + " components · " + chosenAddons().length + " add-ons";
    }
    if ($("plan-note")) {
      $("plan-note").textContent =
        "Steps are filtered by your selection and link to the documents that are the authority. " +
        "Generated files are starting points: review every path, image tag and address.";
    }

    var sbody = $("sizing") ? $("sizing").querySelector("tbody") : null;
    if (sbody) {
      clear(sbody);
      sbody.appendChild(el("tr", {}, [
        el("td", { text: "Role" }), el("td", { text: "Nodes" }),
        el("td", { text: "vCPU" }), el("td", { text: "RAM GiB" }), el("td", { text: "Disk GiB" })
      ]));
      var totalCpu = 0, totalMem = 0, totalDisk = 0;
      sizingRows().forEach(function (r) {
        totalCpu += parseInt(r[1], 10) * parseInt(r[2], 10);
        totalMem += parseInt(r[1], 10) * parseInt(r[3], 10);
        totalDisk += parseInt(r[1], 10) * parseInt(r[4], 10);
        sbody.appendChild(el("tr", {}, r.map(function (c) { return el("td", { text: c }); })));
      });
      sbody.appendChild(el("tr", {}, [
        el("td", { text: "Total" }),
        el("td", { text: String(topologyTotals()) }),
        el("td", { text: String(totalCpu) }),
        el("td", { text: String(totalMem) }),
        el("td", { text: String(totalDisk) })
      ]));
    }

    var vbody = $("versions") ? $("versions").querySelector("tbody") : null;
    if (vbody) {
      clear(vbody);
      var seen = {};
      Object.keys(cm && cm.versions ? cm.versions : {}).forEach(function (k) {
        if (seen[k]) return;
        seen[k] = true;
        vbody.appendChild(el("tr", {}, [
          el("td", { text: k }), el("td", { text: cm.versions[k] })
        ]));
      });
      DATA.components.forEach(function (c) {
        var o = optionOf(c.id);
        if (o && o.versionKey && DATA.versions[o.versionKey] && !seen[o.versionKey]) {
          seen[o.versionKey] = true;
          vbody.appendChild(el("tr", {}, [
            el("td", { text: c.title }), el("td", { text: DATA.versions[o.versionKey] })
          ]));
        }
      });
    }

    var list = $("steps");
    if (list) {
      clear(list);
      DATA.steps.filter(stepApplies).forEach(function (s) {
        var item = el("li", {}, [
          el("div", { class: "step-phase", text: s.phase }),
          el("div", { class: "step-title", text: s.title })
        ]);
        var acts = el("ul", { class: "step-actions" });
        (s.actions || []).forEach(function (a) { acts.appendChild(el("li", { text: a })); });
        item.appendChild(acts);
        var refs = el("div", { class: "step-ref" }, [el("code", { text: s.doc })]);
        (s.extraDocs || []).forEach(function (d) {
          refs.appendChild(el("br"));
          refs.appendChild(el("code", { text: d }));
        });
        item.appendChild(refs);
        list.appendChild(item);
      });
    }

    var box = $("exports");
    if (box) {
      clear(box);
      DATA.exports.forEach(function (exp) {
        if (!exportApplies(exp)) return;
        var body = renderTemplate(exp.template);
        box.appendChild(el("div", { class: "export" }, [
          el("h4", { text: exp.name }),
          el("p", { text: exp.description }),
          el("div", { class: "fname", text: exp.filename }),
          el("pre", { text: body }),
          el("div", { class: "row" }, [
            el("button", {
              class: "btn primary", text: "Download",
              onclick: function () { download(exp.filename, body); toast("Downloaded " + exp.filename); }
            }),
            el("button", {
              class: "btn", text: "Copy",
              onclick: function () { copyText(body); toast("Copied " + exp.filename); }
            })
          ])
        ]));
      });
    }
  }

  function topologyTotals() {
    var t = topology();
    return t.cp.length + t.w.length + t.gpu.length + t.mgmt.length + t.ceph.length + t.edge.length;
  }

  var ADDON_FILES = {
    "certManager:vault-pki": "cert-manager-values.yaml",
    "certManager:selfsigned": "cert-manager-values.yaml",
    "vpa:recommendation": "vpa-values.yaml",
    "vpa:auto": "vpa-auto-values.yaml",
    "descheduler:dry-run": "descheduler-dryrun-values.yaml",
    "descheduler:evict": "descheduler-evict-values.yaml",
    "externalDns:rfc2136": "external-dns-values.yaml",
    "externalDns:coredns-etcd": "external-dns-coredns-values.yaml",
    "trivyOperator:enabled": "trivy-values.yaml",
    "otelCollector:daemonset": "otel-collector.yaml"
  };
  var ADDON_VERIFY = {
    certManager: "kubectl get clusterissuer && kubectl get certificates -A",
    metricsServer: "kubectl get apiservice v1beta1.metrics.k8s.io",
    vpa: "kubectl get vpa -A",
    descheduler: "kubectl -n kube-system get cronjob descheduler",
    externalDns: "kubectl -n external-dns logs deploy/external-dns --tail=20",
    trivyOperator: "kubectl get vulnerabilityreports -A | head",
    otelCollector: "kubectl -n observability get opentelemetrycollector"
  };
  var ADDON_ORDER = ["certManager", "metricsServer", "vpa", "descheduler", "externalDns", "trivyOperator", "otelCollector"];

  function chosenAddons() {
    var out = [];
    ADDON_ORDER.forEach(function (id) {
      var o = optionOf(id);
      if (!o || o.id === "none") return;
      out.push({
        id: id,
        title: o.title,
        file: ADDON_FILES[id + ":" + o.id] || null,
        verify: ADDON_VERIFY[id]
      });
    });
    return out;
  }

  function buildRunbook() {
    var method = DATA.methods.filter(function (m) { return m.id === state.method; })[0];
    var cm = DATA.clusterMethods.filter(function (m) { return m.id === state.cluster; })[0];
    var t = topology();
    var addons = chosenAddons();
    var name = state.values.clusterName;

    var out = ["# Deployment runbook — " + name + " (" + state.values.env + ")", ""];
    out.push("Generated by the cloud-native guide site on " + new Date().toISOString().slice(0, 10) + ".");
    out.push("The automated path is the default. The step list below is what the scripts do, in order,");
    out.push("with the document that explains each decision.");
    out.push("");
    out.push("## Quick start");
    out.push("");
    out.push("Download every generated file into one directory on the admin host, then:");
    out.push("");
    out.push("```bash");
    out.push("chmod +x deploy.sh 0*.sh 1*.sh 2*.sh 3*.sh 4*.sh 5*.sh");
    out.push("./deploy.sh --dry-run     # print every action, change nothing");
    out.push("./deploy.sh               # run every phase, stop at the first failure");
    out.push("./deploy.sh --phase 40    # resume from one phase");
    out.push("./deploy.sh --verify      # re-run only the acceptance checks");
    out.push("```");
    out.push("");
    out.push("Phases: `00` preflight, `10` OS baseline, `20` Ceph, `30` Kubernetes, `40` add-ons, `50` verify.");
    out.push("Every phase is idempotent and writes `logs/<phase>-<timestamp>.log`. A phase that fails stops the run;");
    out.push("fix the cause, re-run the same command. Nothing is skipped silently.");
    out.push("");
    out.push("Files the scripts expect next to `deploy.sh`: `nodes.tsv`, `hosts.ini`, `hosts-mgmt.ini`,");
    out.push("`k8s-cluster-vars.yml`, `ceph-spec.yaml`, `ceph-bootstrap.sh` and the add-on values files listed below.");
    out.push("");
    out.push("## Plan");
    out.push("");
    out.push("| Setting | Value |");
    out.push("|---|---|");
    out.push("| Deployment | " + (method ? method.title : "-") + " |");
    out.push("| Cluster method | " + (cm ? cm.title : "-") + " |");
    out.push("| Nodes (all roles) | " + topologyTotals() + " |");
    DATA.components.forEach(function (c) {
      out.push("| " + c.title + " | " + optionTitle(c.id) + " |");
    });
    out.push("");
    out.push("## Sizing");
    out.push("");
    out.push("| Role | Nodes | vCPU | RAM GiB | Disk GiB |");
    out.push("|---|---|---|---|---|");
    sizingRows().forEach(function (r) { out.push("| " + r.join(" | ") + " |"); });
    out.push("");
    out.push("## Nodes");
    out.push("");
    out.push("| Role | Name | Address |");
    out.push("|---|---|---|");
    function rows(label, list) {
      list.forEach(function (n) { out.push("| " + label + " | " + n.name + " | " + n.ip + " |"); });
    }
    rows("control plane", t.cp);
    rows("worker", t.w);
    rows("gpu", t.gpu);
    rows("management", t.mgmt);
    rows("ceph-mon", t.cephRoles.mon);
    rows("ceph-mgr", t.cephRoles.mgr);
    rows("ceph-osd", t.cephRoles.osd);
    rows("ceph-mds", t.cephRoles.mds);
    rows("ceph-rgw", t.cephRoles.rgw);
    rows("edge", t.edge);
    out.push("");
    out.push("## Phased steps");
    DATA.steps.filter(stepApplies).forEach(function (s, i) {
      out.push("");
      out.push("### " + s.phase + " — " + s.title);
      out.push("");
      (s.actions || []).forEach(function (a) { out.push("- " + a); });
      out.push("");
      out.push("Reference: `" + s.doc + "`");
      (s.extraDocs || []).forEach(function (d) { out.push("- `" + d + "`"); });
      out.push("");
      out.push("Gate: the phase's own verification passes before the next phase starts. If it does not,");
      out.push("stop and fix it. A partially applied phase is re-run, not skipped.");
    });
    out.push("");
    out.push("## Add-ons");
    out.push("");
    if (!addons.length) {
      out.push("No optional add-ons selected. The baseline is complete without them.");
    } else {
      out.push("Install in this order. `40-addons.sh` skips any file that is not present, so the list below");
      out.push("is the contract between the site and the script.");
      out.push("");
      out.push("| # | Add-on | Values file | Verify |");
      out.push("|---|---|---|---|");
      addons.forEach(function (a, i) {
        out.push("| " + (i + 1) + " | " + a.title + " | " + (a.file || "chart defaults") + " | `" + a.verify + "` |");
      });
      out.push("");
      out.push("Order is a dependency chain, not a preference: cert-manager issues the certificates that");
      out.push("external-dns webhooks and ingress controllers consume; Metrics Server feeds VPA and the");
      out.push("descheduler; Trivy and the collector are independent and can be last.");
    }
    out.push("");
    out.push("## Versions");
    out.push("");
    out.push("| Component | Version |");
    out.push("|---|---|");
    Object.keys(DATA.versions).sort().forEach(function (k) {
      out.push("| " + k + " | " + DATA.versions[k] + " |");
    });
    out.push("");
    out.push("## Upgrades");
    out.push("");
    DATA.upgrades.forEach(function (f) {
      out.push("- **" + f.title + "** — rollback: " + f.rollback + " Downtime: " + f.downtime + " Procedure: `" + f.doc + "`");
    });
    out.push("");
    out.push("## When a phase fails");
    out.push("");
    out.push("1. Read the phase log, not the console tail.");
    out.push("2. Re-run the phase in `--dry-run` to see the intended action.");
    out.push("3. Fix the input (address, mirror, credential path) and re-run the same phase.");
    out.push("4. Never hand-edit a generated file in place without correcting the site value that produced it.");
    out.push("");
    out.push("---");
    out.push("");
    out.push("The repository is the authority. Review every document before running a step.");
    return out.join("\n");
  }

  /* ------------------------------------------------------------------ */
  /* upgrade walkthrough                                                */
  /* ------------------------------------------------------------------ */

  function currentFlow() {
    return DATA.upgrades.filter(function (f) { return f.id === state.upgrade.flow; })[0] || null;
  }

  function upgradeTargets(flow) {
    if (!flow) return [];
    if (flow.versionSource === "kubespray") {
      return Object.keys(DATA.clusterMethods[0].versions || {});
    }
    if (flow.versionSource === "istio") {
      return [DATA.versions.istio || "current", "1." + ((parseInt(String(DATA.versions.istio).split(".")[1], 10) || 31) + 1) + ".x (next)"];
    }
    return ["current " + (DATA.versions[flow.versionSource] || "")];
  }

  function renderUpgrade() {
    var sel = $("flow");
    if (!sel) return;
    if (!sel.childNodes || !sel.childNodes.length) {
      DATA.upgrades.forEach(function (f) {
        sel.appendChild(el("option", { value: f.id, text: f.title }));
      });
      state.upgrade.flow = DATA.upgrades[0].id;
      sel.value = state.upgrade.flow;
      sel.onchange = function () {
        state.upgrade.flow = sel.value;
        state.upgrade.target = "";
        renderUpgrade();
      };
    }

    var flow = currentFlow();
    var tsel = $("target");
    if (tsel) {
      clear(tsel);
      var targets = upgradeTargets(flow);
      targets.forEach(function (t) { tsel.appendChild(el("option", { value: t, text: t })); });
      if (state.upgrade.target && targets.indexOf(state.upgrade.target) !== -1) {
        tsel.value = state.upgrade.target;
      } else {
        state.upgrade.target = targets[targets.length - 1] || "";
        tsel.value = state.upgrade.target;
      }
      tsel.onchange = function () { state.upgrade.target = tsel.value; renderUpgradeBody(); };
    }

    if ($("flow-meta")) {
      $("flow-meta").textContent = "Downtime: " + flow.downtime + "   Rollback: " + flow.rollback;
    }
    renderUpgradeBody();
  }

  function renderUpgradeBody() {
    var flow = currentFlow();
    var box = $("upgrade-body");
    if (!flow || !box) return;
    clear(box);

    box.appendChild(el("div", { class: "card plain" }, [
      el("h3", { text: "Target: " + (state.upgrade.target || "current") }),
      el("p", { class: "hint", text: "Procedure: " + flow.doc }),
      el("p", { class: "hint", text: "Steps run top to bottom. A gate that fails stops the upgrade." })
    ]));

    var ol = el("ol", { class: "steps" });
    flow.steps.forEach(function (s) {
      var item = el("li", {}, [
        el("div", { class: "step-phase", text: s.phase + (s.gate ? " · gate" : "") }),
        el("div", { class: "step-title", text: s.title })
      ]);
      var acts = el("ul", { class: "step-actions" });
      (s.actions || []).forEach(function (a) { acts.appendChild(el("li", { text: a })); });
      item.appendChild(acts);
      if (s.command) {
        var cmd = renderTemplate(s.command);
        item.appendChild(el("pre", { text: cmd }));
        item.appendChild(el("div", { class: "row" }, [
          el("button", {
            class: "btn", text: "Copy command",
            onclick: function () { copyText(cmd); toast("Command copied"); }
          })
        ]));
      }
      ol.appendChild(item);
    });
    box.appendChild(ol);
  }

  function buildUpgradeRunbook() {
    var flow = currentFlow();
    if (!flow) return "# no flow selected\n";
    var out = ["# Upgrade runbook — " + flow.title, ""];
    out.push("Cluster: " + state.values.clusterName + " (" + state.values.env + ")");
    out.push("Target: " + (state.upgrade.target || "current"));
    out.push("Procedure: `" + flow.doc + "`");
    out.push("");
    out.push("- Downtime: " + flow.downtime);
    out.push("- Rollback: " + flow.rollback);
    out.push("");
    flow.steps.forEach(function (s, i) {
      out.push("## " + (i + 1) + ". " + s.title + (s.gate ? "  [GATE]" : ""));
      out.push("");
      out.push("_Phase: " + s.phase + "_");
      out.push("");
      (s.actions || []).forEach(function (a) { out.push("- " + a); });
      if (s.command) {
        out.push("");
        out.push("```");
        out.push(renderTemplate(s.command));
        out.push("```");
      }
      out.push("");
    });
    out.push("---");
    out.push("The repository is the authority. A gate that fails stops the upgrade.");
    return out.join("\n");
  }

  /* ------------------------------------------------------------------ */
  /* views and routing                                                  */
  /* ------------------------------------------------------------------ */

  function show(view) {
    state.view = view;
    ["wizard", "review", "upgrade"].forEach(function (v) {
      var node = $(v);
      if (node) node.hidden = v !== view;
    });
    var links = document.querySelectorAll("#nav a[data-view]");
    if (links) {
      for (var i = 0; i < links.length; i++) {
        links[i].className = links[i].getAttribute("data-view") === view ? "on" : "";
      }
    }
    if (view === "review") renderReview();
    if (view === "upgrade") renderUpgrade();
  }

  function route() {
    var h = String(window.location.hash || "").replace("#/", "");
    if (h === "review") return show("review");
    if (h === "upgrade") return show("upgrade");
    var m = h.match(/^page\/([0-9]+)$/);
    if (m) return gotoPage(parseInt(m[1], 10) - 1);
    show("wizard");
    renderCrumbs();
    renderPage();
  }

  /* ------------------------------------------------------------------ */
  /* boot                                                               */
  /* ------------------------------------------------------------------ */

  function initDefaults() {
    state.method = DATA.methods[0].id;
    state.cluster = DATA.clusterMethods[0].id;
    DATA.components.forEach(function (c) {
      if (c.multi) {
        var defs = c.options.filter(function (o) { return o.default; });
        state.choices[c.id] = defs.length ? defs.map(function (o) { return o.id; }) : ["none"];
      } else {
        var def = c.options.filter(function (o) { return o.default; })[0] || c.options[0];
        state.choices[c.id] = def.id;
      }
    });
    DATA.values.forEach(function (v) {
      state.values[v.id] = v.default === undefined ? "" : String(v.default);
    });
    state.upgrade.flow = DATA.upgrades.length ? DATA.upgrades[0].id : null;
    state.upgrade.target = "";
  }

  function boot(data) {
    DATA = data;
    initDefaults();

    if ($("catalog-version")) $("catalog-version").textContent = "catalog " + data.catalogVersion;
    if ($("catalog-updated")) $("catalog-updated").textContent = "updated " + data.updated;
    if ($("version-count")) {
      $("version-count").textContent = Object.keys(data.versions).length + " versions resolved";
    }
    if ($("source-note")) $("source-note").textContent = data.source.docs;

    if ($("prev")) $("prev").onclick = function () { gotoPage(state.page - 1); };
    if ($("next")) {
      $("next").onclick = function () {
        if (state.page === DATA.pages.length - 1) {
          window.location.hash = "#/review";
          show("review");
        } else {
          gotoPage(state.page + 1);
        }
      };
    }
    if ($("download-runbook")) {
      $("download-runbook").onclick = function () {
        download("RUNBOOK-" + state.values.clusterName + "-" + state.values.env + ".md", buildRunbook());
        toast("Runbook downloaded");
      };
    }
    if ($("copy-plan")) {
      $("copy-plan").onclick = function () { copyText(buildRunbook()); toast("Plan copied"); };
    }
    if ($("download-upgrade")) {
      $("download-upgrade").onclick = function () {
        download("UPGRADE-" + (state.upgrade.flow || "flow") + ".md", buildUpgradeRunbook());
        toast("Upgrade runbook downloaded");
      };
    }

    var links = document.querySelectorAll("#nav a[data-view]");
    if (links) {
      for (var i = 0; i < links.length; i++) {
        links[i].addEventListener("click", function (e) {
          if (e && e.preventDefault) e.preventDefault();
          window.location.hash = "#/" + this.getAttribute("data-view");
          route();
        });
      }
    }
    if (window.addEventListener) window.addEventListener("hashchange", route);

    route();
  }

  fetch("data.json")
    .then(function (r) {
      if (!r.ok) throw new Error("data.json " + r.status);
      return r.json();
    })
    .then(boot)
    .catch(function (err) {
      var main = document.querySelector("main");
      if (main && main.insertBefore) {
        main.insertBefore(el("div", { class: "card" }, [
          el("h3", { text: "The site data could not be loaded." }),
          el("p", { text: String(err) }),
          el("p", { class: "hint", text: "Run: python3 scripts/build_site.py, then reload." })
        ]), main.firstChild.nextSibling);
      }
    });

  /* exposed for tests/test_site_render.py; not used by the page itself */
  window.__guide = {
    boot: boot,
    state: state,
    derived: derived,
    renderTemplate: renderTemplate,
    renderPage: renderPage,
    renderReview: renderReview,
    renderUpgrade: renderUpgrade,
    buildRunbook: buildRunbook,
    buildUpgradeRunbook: buildUpgradeRunbook,
    gotoPage: gotoPage
  };
})();
